static void wgpu_upload_font_texture(WGPUContext* ctx, WGPURenderTexture* rt) {
    if (!ctx || !rt) return;

    WGPUTexelCopyTextureInfo destination = {
        .texture = rt->texture,
        .mipLevel = 0,
        .origin = { .x = 0, .y = 0, .z = 0 },
        .aspect = WGPUTextureAspect_All,
    };

    WGPUTexelCopyBufferLayout data_layout = {
        .offset = 0,
        .bytesPerRow = 512 * 4,
        .rowsPerImage = 512,
    };

    WGPUExtent3D write_size = {
        .width = 512,
        .height = 512,
        .depthOrArrayLayers = 1,
    };

    wgpuQueueWriteTexture(ctx->queue, &destination, font_data_bytes, sizeof(font_data_bytes), &data_layout, &write_size);
}

static WGPUBindGroup wgpu_create_gui_bind_group(
    WGPUContext* ctx,
    WGPUGeomPipelineWrapper* pipe_wrapper,
    WGPUUniformBufferWrapper* ubo_wrapper,
    WGPUSampler sampler,
    WGPURenderTexture* texture)
{
    if (!ctx || !pipe_wrapper || !ubo_wrapper || !sampler || !texture) {
        return NULL;
    }

    WGPUBindGroupEntry entries[3] = {
        {
            .binding = 0,
            .buffer = ubo_wrapper->buffer,
            .offset = 0,
            .size = ubo_wrapper->size,
        },
        {
            .binding = 1,
            .sampler = sampler,
        },
        {
            .binding = 2,
            .textureView = texture->view,
        }
    };

    WGPUBindGroupDescriptor desc = {
        .layout = pipe_wrapper->bgl,
        .entryCount = 3,
        .entries = entries,
    };

    return wgpuDeviceCreateBindGroup(ctx->device, &desc);
}

